Fixpoint list_set {T} (l : list T) (i : nat) (x : T) : list T :=
  match l, i with
  | [], _ => []
  | _ :: t, O => x :: t
  | h :: t, S i' => h :: list_set t i' x
  end.

Lemma list_set_length : forall {T} (l : list T) i x, length (list_set l i x) = length l.
Proof using Type.
